{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Aromatherapy Care in {{CITY}}, {{STATE}}</title>
  <meta name="description" content="Practical, safety-first aromatherapy sessions with {{PRACTITIONER_NAME}}. Blends, education, and private VIP Day intensives." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-clinic">
  <header class="site-header">
    <div class="inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="mainNav">
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Blends</a>
        <a href="/shop.html">Shop</a>
        <a href="/pricing.html">Rates</a>
        <a href="/about.html">About</a>
        <a href="/book.html" class="cta">Book</a>
        <a href="/contact.html">Connect</a>
      </nav>
      <button class="nav-toggle" id="navToggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO: sensory invitation with safety-first note -->
    <section class="hero" id="hero">
      <div class="hero-inner">
        <div class="hero-copy">
          <h1>{{TAGLINE}}</h1>
          <p class="lede">Evidence-informed aromatherapy for everyday wellbeing. Gentle blends, clear guidance, and an emphasis on safe use for you and those in your care.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn outline" href="/about.html">Meet {{PRACTITIONER_NAME}}</a>
          </div>
          <p class="safety">Note: Aromatherapy complements wellness routines but is not a substitute for medical care. Always consult your healthcare provider for health concerns.</p>
        </div>
        <div class="hero-visual">
          <svg class="svg-ripple" viewBox="0 0 600 400" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0%" stop-color="#e6f1ea" />
                <stop offset="100%" stop-color="#f6efe6" />
              </linearGradient>
            </defs>
            <rect width="100%" height="100%" fill="url(#g1)" />
            <g opacity="0.8" fill="none" stroke-linecap="round" stroke-width="12">
              <path stroke="#d1e7dc" d="M30 350 C150 250 250 450 370 330" />
              <path stroke="#f0e6de" d="M40 300 C160 200 260 400 380 280" />
            </g>
            <g class="leaf" transform="translate(420,60)">
              <ellipse cx="0" cy="0" rx="40" ry="18" fill="#cfeadf" transform="rotate(-30)" />
              <ellipse cx="10" cy="10" rx="30" ry="12" fill="#eaf6ef" transform="rotate(10)" />
            </g>
          </svg>
        </div>
      </div>
      <svg class="pattern" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" aria-hidden="true"><defs><pattern id="p" width="20" height="20" patternUnits="userSpaceOnUse"><rect width="20" height="20" fill="rgba(255,255,255,0.02)"/><circle cx="10" cy="10" r="6" fill="rgba(0,0,0,0.02)"/></pattern></defs><rect width="100%" height="100%" fill="url(#p)"/></svg>
    </section>

    <!-- SOCIAL PROOF: subtle client quotes, logos -->
    <section class="social-proof">
      <div class="inner">
        <h2>Trusted locally</h2>
        <p class="muted">Loved by clients in {{CITY}} and beyond for thoughtful blends and clear precautions.</p>
        <div class="proof-grid">
          <blockquote class="quote">"Practical, calming, and always mindful of safety — I learned how to use oils at home without guesswork."<cite>— S. from {{CITY}}</cite></blockquote>
          <blockquote class="quote">"A gentle approach that respects pregnancy guidance and pet safety. Highly recommended."<cite>— R. in {{STATE}}</cite></blockquote>
          <div class="logos">
            <span class="badge">Community Clinic Partner</span>
            <span class="badge">Holistic Co-op</span>
          </div>
        </div>
      </div>
    </section>

    <!-- BENEFITS: three-column features with safety lens -->
    <section class="benefits">
      <div class="inner">
        <h2>What you gain</h2>
        <div class="cards">
          <article class="card">
            <strong>Tailored Blends</strong>
            <p>Personalized aroma plans that account for age, pregnancy, medications, and pets. Every blend includes a clear dilution plan.</p>
          </article>
          <article class="card">
            <strong>Practical Education</strong>
            <p>Step-by-step guidance: patch testing, storage, and safe topical use — practical skills you can apply immediately.</p>
          </article>
          <article class="card">
            <strong>VIP Day Option</strong>
            <p>Intensive, hands-on session (VIP Day) to build an at-home aromatherapy routine and curated blends in one focused day.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- PROCESS: how a session unfolds (unique order) -->
    <section class="process">
      <div class="inner">
        <h2>Your session—simple steps</h2>
        <ol class="steps">
          <li>
            <h3>1. Intake & Safety Review</h3>
            <p>We review medical history, current meds, pregnancy/pet considerations, and any allergies to select safe oils.</p>
          </li>
          <li>
            <h3>2. Sensory Sampling</h3>
            <p>Smell and sample micro-dilutions to build preference while watching for sensitivities through patch testing methods.</p>
          </li>
          <li>
            <h3>3. Personalized Blend & Plan</h3>
            <p>Leave with labeled blends, dilution instructions, and written safety notes for home use.</p>
          </li>
        </ol>
      </div>
    </section>

    <!-- LEAD MAGNET: downloadable safety-first guide -->
    <section class="lead-magnet" id="lead">
      <div class="inner">
        <div class="lead-copy">
          <h2>Free: At-Home Aromatherapy Safety Guide</h2>
          <p>Download the quick guide that covers dilution charts, patch test steps, pet & pregnancy notes, and storage tips.</p>
          <form id="leadForm" class="lead-form">
            <label class="visually-hidden" for="lm-email">Email</label>
            <input id="lm-email" name="email" type="email" placeholder="Your email address" required />
            <button type="submit" class="btn primary">Get the Guide</button>
          </form>
          <p class="muted">We respect your privacy. No spam — just the guide and occasional updates about VIP Day availability.</p>
        </div>
        <div class="lead-art">
          <svg width="240" height="200" viewBox="0 0 240 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
            <rect rx="8" ry="8" width="100%" height="100%" fill="#f6f3ef" />
            <g transform="translate(20,30)">
              <rect width="80" height="26" rx="4" fill="#dfefe5" />
              <rect y="44" width="160" height="12" rx="4" fill="#e9f6ee" />
              <rect y="64" width="140" height="12" rx="4" fill="#e9f6ee" />
              <circle cx="170" cy="30" r="22" fill="#cfeadf" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- FAQ: safety-first answers -->
    <section class="faq" id="faq">
      <div class="inner">
        <h2>Common questions</h2>
        <div class="qa">
          <button class="q">How do I dilute essential oils safely?</button>
          <div class="a">Dilution depends on the application, age, and condition. Typical guidelines: 1% for children/elderly, 1.5–3% for daily adult topical use. Your session includes a clear dilution chart tailored to your needs. These are general recommendations and not medical advice.</div>
        </div>
        <div class="qa">
          <button class="q">What is a patch test?</button>
          <div class="a">A patch test applies a small diluted amount to a discreet skin area and observes for 24–48 hours. We walk you through safe patch testing during your appointment to check for sensitivities.</div>
        </div>
        <div class="qa">
          <button class="q">Are blends safe around pets?</button>
          <div class="a">Some oils are not safe near pets. We always ask about animals in the household and provide pet-safe alternatives and usage notes — including diffusion duration limits and ventilation practices.</div>
        </div>
        <div class="qa">
          <button class="q">Can I use essential oils during pregnancy?</button>
          <div class="a">Certain oils and high concentrations are best avoided during pregnancy. We adhere to conservative, safety-first guidance and will create pregnancy-appropriate blends or recommend alternatives.</div>
        </div>
      </div>
    </section>

    <!-- FINAL CTA: booking block with VIP day mention -->
    <section class="final-cta">
      <div class="inner">
        <h2>Ready to create your safe aromatherapy plan?</h2>
        <p>Book a session or inquire about a focused VIP Day to build a routine and blends in one immersive visit.</p>
        <div class="actions">
          <a class="btn primary" href="/book.html">Schedule a Session</a>
          <a class="btn outline" href="/pricing.html">See Rates & VIP Day</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="inner">
      <div class="contact">
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}} · <a href="tel:{{PHONE}}">{{PHONE}}</a> · <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
      <nav class="foot-nav">
        <a href="/about.html">About</a>
        <a href="/blends.html">Blends</a>
        <a href="/shop.html">Shop</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <small class="muted">© <span id="year"></span> {{BUSINESS_NAME}} · Aromatherapy services and education. Not medical advice.</small>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
