{"path":"assets/css/styles.css","content":"/* Clinic modern theme — CSS only, no external assets */
:root{--bg:#fbfbf9;--card:#fff;--muted:#6c6c6c;--brand:#2f7a63;--accent:#8fcfb1;--accent-2:#e6f2ea;--glass:rgba(255,255,255,0.6)}
*{box-sizing:border-box}html,body{height:100%}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#213;line-height:1.4;background:linear-gradient(180deg,var(--bg),#f8fbf7)}
.inner{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(90deg,rgba(255,255,255,0.6),rgba(255,255,255,0.3));backdrop-filter:blur(6px);position:sticky;top:0;z-index:30;border-bottom:1px solid rgba(34,50,40,0.04)}
.site-header .inner{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--brand);text-decoration:none;font-size:1.15rem}
.nav{margin-left:auto;display:flex;gap:12px}
.nav a{color:#2b2b2b;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta{background:var(--brand);color:white}
.nav-toggle{display:none;background:none;border:0;font-size:1.3rem}

.hero{padding:48px 0 12px;position:relative;overflow:hidden}
.hero-inner{display:grid;grid-template-columns:1fr 420px;gap:24px;align-items:center}
.hero-copy h1{font-size:2.1rem;margin:0;color:#1f4f3f}
.lede{color:var(--muted);margin-top:8px}
.hero-actions{margin-top:16px;display:flex;gap:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:8px;text-decoration:none;border:1px solid transparent}
.btn.primary{background:var(--brand);color:#fff}
.btn.outline{background:transparent;border:1px solid rgba(47,122,99,0.12);color:var(--brand)}
.safety{font-size:0.85rem;color:var(--muted);margin-top:10px}
.hero-visual{display:flex;justify-content:center}
.svg-ripple{width:100%;height:100%;max-width:440px}
.pattern{position:absolute;right:0;top:0;width:38%;height:100%;opacity:0.28;transform:translateX(12%)}

.social-proof{padding:28px 0}
.social-proof h2{margin:0 0 8px 0;color:#1f4f3f}
.proof-grid{display:grid;grid-template-columns:1fr 1fr auto;gap:14px;align-items:center}
.quote{background:var(--card);padding:16px;border-radius:10px;box-shadow:0 6px 18px rgba(12,30,20,0.04);border:1px solid rgba(40,70,56,0.03)}
.quote cite{display:block;margin-top:8px;color:var(--muted);font-size:0.9rem}
.logos{display:flex;flex-direction:column;gap:8px}
.badge{background:var(--accent-2);padding:8px 12px;border-radius:8px;color:var(--brand);font-weight:600}

.benefits{padding:18px 0}
.benefits h2{color:#1f4f3f}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:12px}
.card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(34,72,58,0.04)}
.card strong{display:block;margin-bottom:8px;color:var(--brand)}

.process{padding:18px 0}
.steps{list-style:none;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.steps li{background:linear-gradient(180deg,#fff,#fbfdfb);padding:16px;border-radius:12px;border:1px solid rgba(34,72,58,0.04)}
.steps h3{margin:0 0 8px 0;color:var(--brand)}

.lead-magnet{padding:28px 0;background:linear-gradient(180deg,#fff,#fbfff9);border-top:1px dashed rgba(40,80,60,0.03);border-bottom:1px dashed rgba(40,80,60,0.03)}
.lead-magnet .inner{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:center}
.lead-form{display:flex;gap:8px}
.lead-form input{padding:10px;border-radius:8px;border:1px solid rgba(34,72,58,0.08);flex:1}
.lead-art{display:flex;justify-content:center}

.faq{padding:18px 0}
.faq h2{color:var(--brand)}
.qa{margin-top:12px}
.q{width:100%;text-align:left;padding:12px;border-radius:10px;border:1px solid rgba(34,72,58,0.06);background:#fff;font-weight:600}
.a{display:none;padding:12px;border-left:3px solid var(--accent);margin-top:6px;background:#fff;border-radius:8px}

.final-cta{padding:32px 0;background:linear-gradient(90deg,rgba(143,207,177,0.06),rgba(230,242,234,0.06));border-radius:12px;margin:18px 0}
.final-cta .actions{display:flex;gap:12px;margin-top:12px}

.site-footer{padding:24px 0;background:transparent;border-top:1px solid rgba(34,50,40,0.03)}
.site-footer .inner{display:flex;gap:12px;align-items:center;justify-content:space-between}
.foot-nav a{margin-left:8px;color:var(--muted);text-decoration:none}
.muted{color:var(--muted)}
.visually-hidden{position:absolute!important;height:1px;width:1px;overflow:hidden;clip:rect(1px,1px,1px,1px);white-space:nowrap}

/* Responsive */
@media(max-width:900px){
  .hero-inner{grid-template-columns:1fr;}
  .nav{display:none;position:absolute;right:18px;top:64px;background:var(--card);flex-direction:column;padding:12px;border-radius:8px;box-shadow:0 12px 40px rgba(0,0,0,0.08)}
  .nav-toggle{display:block;margin-left:auto}
  .proof-grid{grid-template-columns:1fr}
  .cards{grid-template-columns:1fr}
  .steps{grid-template-columns:1fr}
  .lead-magnet .inner{grid-template-columns:1fr}
  .site-footer .inner{flex-direction:column;align-items:flex-start}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Mobile nav toggle
  var navToggle=document.getElementById('navToggle');
  var mainNav=document.getElementById('mainNav');
  navToggle&&navToggle.addEventListener('click',function(){
    if(mainNav.style.display==='flex'){mainNav.style.display='none'}else{mainNav.style.display='flex'}
  });

  // FAQ accordion
  var qs=document.querySelectorAll('.faq .qa');
  qs.forEach(function(node){
    var btn=node.querySelector('.q');
    var ans=node.querySelector('.a');
    btn.addEventListener('click',function(){
      var open=ans.style.display==='block';
      // close others
      document.querySelectorAll('.faq .a').forEach(function(x){x.style.display='none'});
      if(!open) ans.style.display='block';
    });
  });

  // Lead magnet form handling (UI only)
  var lead=document.getElementById('leadForm');
  lead&&lead.addEventListener('submit',function(e){
    e.preventDefault();
    var email=(lead.querySelector('input[name="email"]').value||'').trim();
    if(!email||!email.includes('@')){
      alert('Please enter a valid email address to receive the guide.');
      return;
    }
    // simulate success
    lead.querySelector('input[name="email"]').value='';
    alert('Thanks! The safety guide is on its way to ' + email + '.');
  });

  // Insert current year
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // Basic accessibility: focus outlines for keyboard users
  function handleFirstTab(e){if(e.key==='Tab'){document.body.classList.add('show-focus-outlines');window.removeEventListener('keydown',handleFirstTab)} }
  window.addEventListener('keydown',handleFirstTab);
});"} 
